import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../../core/widgets/zaylo_widgets.dart';import '../../repositories/providers.dart';
class FuelScreen extends ConsumerWidget{const FuelScreen({super.key});@override Widget build(BuildContext context,WidgetRef ref)=>Scaffold(appBar:AppBar(title:const Text('Fuel Prices')),body:ListView(padding:const EdgeInsets.all(16),children:[const TextField(decoration:InputDecoration(hintText:'Filter by city or fuel type')),for(final f in ref.watch(mockRepositoryProvider).fuel()) ZayloCard(child:ListTile(title:Text(f.station),subtitle:Text('${f.city} • last updated ${f.updatedAt.hour}:30'),trailing:Column(mainAxisSize:MainAxisSize.min,children:[Text('Petrol \$${f.petrol}'),Text('Diesel \$${f.diesel}'),TrustBadge(f.verified)])))]));}
